//! Shaka Packager operations for merging, decrypting, and encrypting media.
//!
//! Segment duration is required and source-derived. The IV is supplied explicitly;
//! protection-system headers are passed as opaque bytes rather than generated by
//! `--protection_systems`. Per-segment encryption preserves source boundaries.
//!
//! Raw-key mode requires the content key and IV in child arguments. Every child runs
//! through the shared tool runner without a shell. Logs contain redacted arguments
//! and scrubbed output; spawn failures and timeouts expose fixed messages only.
//! Results carry redacted arguments and a scrubbed stderr tail. The key identifier
//! is public, but content keys, IVs, and operator signaling addresses remain private.

use crate::canonical::python_float_repr;
use crate::config::KeyMaterial;
use crate::pycompat::{GlobError, PurePosixPath, glob, int, repr_int_list};
use crate::toolrun::{REDACTED, RunOptions, ToolRunner, patterns_for, universal_newlines};
use regex::Regex;
use std::collections::BTreeMap;
use std::fmt;
use std::fs::File;
use std::io::ErrorKind;
use std::path::{Path, PathBuf};
use std::sync::{Arc, LazyLock};
use std::time::{Duration, Instant};
use zeroize::Zeroizing;

/// Only the last this-many characters of stderr stay on a result (enough to diagnose without
/// hoarding); the complete output, scrubbed and bounded, goes to the job log.
pub const STDERR_TAIL_CHARS: usize = 4000;

/// The isolating `--segment_duration` of the per-source-segment path (1e6 s, 11.5 days).
///
/// Encrypt each source segment separately to preserve its original boundaries.
/// A continuous stream would be split on a fixed timestamp grid; AAC frames do not
/// necessarily divide that grid evenly. An isolating duration longer than the input
/// forces a single output segment. Validate that postcondition rather than changing
/// manifest boundaries to conceal a media mismatch.
pub const ISOLATING_SEGMENT_DURATION_S: f64 = 1_000_000.0;

/// Returned when the isolating duration fails to isolate (Shaka emits more than one segment
/// for one source segment): not a packager exit code but a post-condition breach the caller
/// must treat as FAIL rather than silently dropping data.
pub const ISOLATION_VIOLATION_RC: i32 = 251;

/// The first run of digits in a segment file stem (a few lines duplicated from `config` on
/// purpose).
static SEGMENT_NUMBER: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(\d+)").expect("a fixed pattern compiles"));

/// The packager could not be run to completion: a spawn failure or a timeout
/// (`PackagerError`). It carries ONLY a fixed message and the redacted argv — never the key or
/// the IV, and no cause that could lead back to them (`source` is `None`).
#[derive(Clone, PartialEq, Eq, thiserror::Error)]
#[error("{message}")]
pub struct PackagerError {
    message: String,
    argv_redacted: Vec<String>,
}

impl PackagerError {
    /// `PackagerError(message, argv_redacted=...)`.
    pub fn new(message: impl Into<String>, argv_redacted: Vec<String>) -> Self {
        PackagerError {
            message: message.into(),
            argv_redacted,
        }
    }

    /// The message, as Python's `str(error)`.
    pub fn message(&self) -> &str {
        &self.message
    }

    /// The argv with the key and the IV masked (the KID visible).
    pub fn argv_redacted(&self) -> &[String] {
        &self.argv_redacted
    }
}

impl fmt::Debug for PackagerError {
    /// The message and the argv's length: the redacted argv still carries the `--pssh` hex,
    /// whose `PlayReady` object holds a clear-HLS operator's `LA_URL`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("PackagerError")
            .field("message", &self.message)
            .field("argv_tokens", &self.argv_redacted.len())
            .finish()
    }
}

/// The outcome of one Shaka Packager run (`PackagerResult`). Carries no key and no IV.
#[derive(Clone, PartialEq)]
pub struct PackagerResult {
    /// The argv with the key and the IV masked; the KID (public) visible.
    pub argv_redacted: Vec<String>,
    /// The exit code (a negative signal number when a signal ended the tool), or
    /// [`ISOLATION_VIOLATION_RC`].
    pub returncode: i32,
    /// Seconds spent running the tool(s).
    pub duration_s: f64,
    /// The last [`STDERR_TAIL_CHARS`] characters of stderr, scrubbed of the key and the IV.
    pub stderr_tail: String,
}

impl fmt::Debug for PackagerResult {
    /// Sizes only, for the reason [`PackagerError`]'s `Debug` gives.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("PackagerResult")
            .field("argv_tokens", &self.argv_redacted.len())
            .field("returncode", &self.returncode)
            .field("duration_s", &self.duration_s)
            .field("stderr_tail_chars", &self.stderr_tail.chars().count())
            .finish()
    }
}

/// What a packager function can raise, by the Python exception class: the [`PackagerError`]
/// of a run that could not complete, a `ValueError` (a segment file without a number, a
/// non-contiguous staging series, a duration that is not a finite number), an `OSError`.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// `PackagerError`.
    #[error(transparent)]
    Packager(#[from] PackagerError),
    /// `ValueError`, with a compatible message.
    #[error("{0}")]
    Value(String),
    /// `OSError`.
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

impl From<GlobError> for Error {
    fn from(error: GlobError) -> Self {
        match error {
            GlobError::Io(error) => Error::Io(error),
            other => Error::Value(other.to_string()),
        }
    }
}

// ------------------------------------------------------------------------------------------
// merge
// ------------------------------------------------------------------------------------------

/// A segment's integer index (`ls -V` / `sort -V` semantics without a shell).
fn numeric_segment_key(path: &Path) -> Result<i64, Error> {
    let posix = PurePosixPath::from_path(path);
    let found = SEGMENT_NUMBER
        .find(posix.stem())
        .ok_or_else(|| Error::Value(format!("segment file {posix} has no numeric index")))?;
    int(found.as_str()).map_err(Error::Value)
}

/// `str(Path(path))` as a native path (the original when it is not UTF-8).
fn py_path(path: &Path) -> PathBuf {
    if path.to_str().is_some() {
        PurePosixPath::from_path(path).to_path_buf()
    } else {
        path.to_path_buf()
    }
}

/// `path.mkdir(parents=True, exist_ok=True)`.
fn make_dirs(path: &Path) -> Result<(), Error> {
    #[cfg(unix)]
    std::fs::create_dir_all(path)?;
    #[cfg(windows)]
    crate::native::create_media_dir_all(path)?;
    Ok(())
}

/// The parent directory of a path, as `pathlib` computes it (`.` for a bare name).
fn parent_of(path: &Path) -> PathBuf {
    if path.to_str().is_some() {
        PurePosixPath::from_path(path).parent().to_path_buf()
    } else {
        path.parent()
            .map_or_else(|| PathBuf::from("."), Path::to_path_buf)
    }
}

/// Concatenate `init || seg_0 || seg_1 || … || seg_N` as pure bytes in NUMERIC segment order
/// (without invoking a shell): the segments may
/// come in any order. Byte-exact by construction; streamed, so a large rendition
/// never sits in memory whole. Also the CBCS re-merge of the 6-4 round trip.
///
/// HARD INVARIANT (inputs read-only): reads `init_path` and `segment_paths`, writes only
/// `output_path`.
pub fn merge_segments(
    init_path: &Path,
    segment_paths: &[PathBuf],
    output_path: &Path,
) -> Result<PathBuf, Error> {
    let output_path = py_path(output_path);
    #[cfg(unix)]
    make_dirs(&parent_of(&output_path))?;
    let mut keyed = Vec::with_capacity(segment_paths.len());
    for segment in segment_paths {
        keyed.push((numeric_segment_key(segment)?, segment));
    }
    keyed.sort_by_key(|(key, _)| *key); // stable, as Python's sorted
    let mut out = crate::media::create_output_file(&output_path)?;
    // The inputs as `Path(...)` spells them: `init.mp4/` or `./init.mp4` name `init.mp4`.
    std::io::copy(&mut File::open(py_path(init_path))?, &mut out)?;
    for (_, segment) in keyed {
        std::io::copy(&mut File::open(py_path(segment))?, &mut out)?;
    }
    Ok(output_path)
}

// ------------------------------------------------------------------------------------------
// startNumber reconciliation
// ------------------------------------------------------------------------------------------

/// [`renumber_to_source_origin_with`] for Shaka's `seg_<n>.m4s` staging names.
pub fn renumber_to_source_origin(
    staging_dir: &Path,
    source_start_number: i64,
) -> Result<BTreeMap<i64, i64>, Error> {
    renumber_to_source_origin_with(staging_dir, source_start_number, "seg_", ".m4s")
}

/// Rename staged Shaka output segments to the source numbering origin.
/// Return the mapping and let the caller verify the output count. Output filenames
/// change while manifest URLs and `startNumber` remain unchanged. A source origin of
/// zero maps `seg_1` to `seg_0`; one preserves the staged numbers. Reject gaps or
/// unexpected numbering rather than accepting an incomplete staging series.
pub fn renumber_to_source_origin_with(
    staging_dir: &Path,
    source_start_number: i64,
    prefix: &str,
    suffix: &str,
) -> Result<BTreeMap<i64, i64>, Error> {
    let mut staged: Vec<(i64, PathBuf)> = Vec::new();
    for entry in std::fs::read_dir(staging_dir)? {
        let path = staging_dir.join(entry?.file_name());
        let name: Vec<char> = path
            .file_name()
            .map(|name| name.to_string_lossy().chars().collect())
            .unwrap_or_default();
        let text: String = name.iter().collect();
        if path.is_file() && text.starts_with(prefix) && text.ends_with(suffix) {
            // `name[len(prefix):-len(suffix)]`, an empty slice when the two overlap.
            let start = prefix.chars().count();
            let end = name.len() - suffix.chars().count();
            let index_text: String = name
                .get(start..end.max(start))
                .unwrap_or(&[])
                .iter()
                .collect();
            staged.push((int(&index_text).map_err(Error::Value)?, path));
        }
    }
    staged.sort();
    if staged.is_empty() {
        return Ok(BTreeMap::new());
    }
    let numbers: Vec<i64> = staged.iter().map(|(number, _)| *number).collect();
    if !numbers
        .iter()
        .copied()
        .eq(1..=i64::try_from(staged.len()).unwrap_or(i64::MAX))
    {
        return Err(Error::Value(format!(
            "staged segments are not the contiguous 1..N Shaka emits: {}",
            repr_int_list(&numbers)
        )));
    }
    // dst = shaka_number + (source_start_number - 1), a uniform shift, renamed in the order
    // that never overwrites a not-yet-renamed source: down => ascending, up => descending.
    let shifted = |number: i64| {
        source_start_number
            .checked_sub(1)
            .and_then(|shift| number.checked_add(shift))
            .ok_or_else(|| Error::Value("startNumber out of the 64-bit range".to_string()))
    };
    let mut plan = Vec::with_capacity(staged.len());
    let mut mapping = BTreeMap::new();
    for (number, path) in &staged {
        let target = shifted(*number)?;
        mapping.insert(*number, target);
        plan.push((
            path.clone(),
            path.with_file_name(format!("{prefix}{target}{suffix}")),
        ));
    }
    if source_start_number > 1 {
        plan.reverse();
    }
    for (source, destination) in plan {
        if source != destination {
            std::fs::rename(&source, &destination)?;
        }
    }
    Ok(mapping)
}

