// the subprocess wrapper
// ------------------------------------------------------------------------------------------

/// The `--keys` value. The content key is masked when `redact` is set; the KID stays visible
/// either way (public,; useful for operations).
fn keys_arg(key: &KeyMaterial, redact: bool) -> String {
    let key_field = if redact { REDACTED } else { key.key_hex() };
    format!("label=:key_id={}:key={key_field}", key.key_id_hex())
}

/// The `--segment_duration` text (`_format_duration`): a whole number of seconds without a
/// trailing `.0` (an integer form), otherwise Python's float repr. A duration that
/// is not finite is Python's error (`int` of NaN or infinity).
pub fn format_duration(seconds: f64) -> Result<String, Error> {
    if seconds.is_nan() {
        return Err(Error::Value(
            "cannot convert float NaN to integer".to_string(),
        ));
    }
    if seconds.is_infinite() {
        // An OverflowError in Python (not a ValueError); the message is the same.
        return Err(Error::Value(
            "cannot convert float infinity to integer".to_string(),
        ));
    }
    if seconds.fract() == 0.0 {
        // `str(int(seconds))`: the exact integer value of the double (`-0.0` prints `0`).
        let text = format!("{seconds:.0}");
        return Ok(if text == "-0" { "0".to_string() } else { text });
    }
    Ok(python_float_repr(seconds))
}

/// `_scrub(text, secrets)`: every secret replaced by [`REDACTED`] as written, lower-cased and
/// upper-cased — applied to the WHOLE stderr before it is tailed, so a secret straddling the
/// tail boundary cannot survive. This legacy helper keeps its literal-only API behavior;
/// tool logs and retained runtime diagnostics use the shared `Secrets` encoding scrub.
pub fn scrub(text: &str, secrets: &[&str]) -> String {
    // Python iterates the set {secret, lower, upper} in hash order; the variants of a hex
    // secret never overlap one another, so this fixed order gives the same text.
    let mut text = text.to_string();
    for secret in secrets.iter().filter(|secret| !secret.is_empty()) {
        let mut variants: Vec<Zeroizing<String>> = vec![Zeroizing::new((*secret).to_string())];
        for variant in [secret.to_lowercase(), secret.to_uppercase()] {
            let variant = Zeroizing::new(variant);
            if !variants.contains(&variant) {
                variants.push(variant);
            }
        }
        for variant in &variants {
            text = text.replace(variant.as_str(), REDACTED);
        }
    }
    text
}

/// The last `limit` characters of `text` (`text[-limit:]`).
fn tail_chars(text: &str, limit: usize) -> String {
    let count = text.chars().count();
    text.chars().skip(count.saturating_sub(limit)).collect()
}

/// Tool runner, binary selection, and per-call timeout for Shaka Packager.
/// Every call uses the shared runner for recording and secret scrubbing.
/// The default binary is `packager` and there is no per-call timeout; batch
/// supervision applies its own retry and asset-deadline policy.
#[derive(Clone)]
pub struct Packager {
    runner: Arc<ToolRunner>,
    binary: String,
    timeout_s: Option<f64>,
}

impl fmt::Debug for Packager {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Packager")
            .field("packager_bin", &self.binary)
            .field("timeout_s", &self.timeout_s)
            .finish_non_exhaustive()
    }
}

// Keep each admitted content job single-threaded and avoid per-file threaded I/O caches.
pub(crate) const RESOURCE_FLAGS: [&str; 2] = ["--single_threaded", "--io_cache_size=0"];

impl Packager {
    /// Shaka Packager as `packager` on the `PATH`, no timeout, through `runner`.
    pub fn new(runner: Arc<ToolRunner>) -> Self {
        Packager {
            runner,
            binary: "packager".to_string(),
            timeout_s: None,
        }
    }

    /// The binary to run, as written (a `str` `packager_bin` is not normalized in Python).
    #[must_use]
    pub fn with_packager_bin(mut self, packager_bin: impl Into<String>) -> Self {
        self.binary = packager_bin.into();
        self
    }

    /// The timeout of each run in seconds (`_SUBPROCESS_TIMEOUT_S`); `None` waits for ever. A
    /// negative value times out at once; a NaN is no timeout.
    #[must_use]
    pub fn with_timeout(mut self, timeout_s: Option<f64>) -> Self {
        self.timeout_s = timeout_s;
        self
    }

    /// The binary this packager runs.
    pub fn packager_bin(&self) -> &str {
        &self.binary
    }

    /// Run the packager through the shared tool runner and return a secret-free result
    /// (`_run_packager`).
    ///
    /// A non-zero exit is NOT an error: it is returned in `returncode` (with the scrubbed
    /// stderr tail) for the orchestration layer to judge. Only a run that cannot complete — a
    /// spawn failure or the timeout — is an error, always the fixed-message [`PackagerError`]:
    /// the tool runner's error names only the tool and the kind, and nothing of it is kept.
    fn run_packager(
        &self,
        argv_real: &[String],
        argv_redacted: Vec<String>,
        secrets: &[&str],
    ) -> Result<PackagerResult, Error> {
        let mut argv_real = zeroize::Zeroizing::new(argv_real.to_vec());
        argv_real.extend(RESOURCE_FLAGS.map(String::from));
        let mut call_secrets = secrets.to_vec();
        call_secrets.extend(
            argv_real
                .windows(2)
                .filter(|pair| pair[0] == "--pssh")
                .map(|pair| pair[1].as_str()),
        );
        let patterns: Vec<_> = call_secrets
            .iter()
            .flat_map(|secret| patterns_for(secret))
            .collect();
        let mut argv_redacted = argv_redacted;
        let mut opaque_pssh = false;
        for argument in &mut argv_redacted {
            if opaque_pssh {
                *argument = REDACTED.into();
                opaque_pssh = false;
            } else {
                opaque_pssh = argument == "--pssh";
                *argument = self
                    .runner
                    .secrets()
                    .scrub_with_patterns(argument, &patterns);
            }
        }
        argv_redacted.extend(RESOURCE_FLAGS.map(String::from));
        let timeout = self
            .timeout_s
            .filter(|seconds| !seconds.is_nan())
            .and_then(|seconds| Duration::try_from_secs_f64(seconds.max(0.0)).ok());
        let options = RunOptions {
            // The runner records ONLY the redacted argv, and scrubs this call's key and IV
            // (plus the job's registered secrets) from the output it records.
            argv_redacted: Some(&argv_redacted),
            secrets: &call_secrets,
            timeout,
            text: true,
            ..RunOptions::default()
        };
        let start = Instant::now();
        let completed = match self.runner.run_tool(&argv_real, "packager", &options) {
            Ok(completed) => completed,
            Err(failure) => {
                let message = if failure.kind == "timeout" {
                    format!(
                        "Shaka Packager timed out after {}s",
                        python_float_repr(self.timeout_s.unwrap_or_default())
                    )
                } else {
                    // A spawn failure (a missing binary): a fixed message; the OS detail
                    // reaches only the job log, scrubbed, in the tool-output record.
                    "could not run Shaka Packager".to_string()
                };
                return Err(PackagerError::new(message, argv_redacted).into());
            }
        };
        let duration_s = start.elapsed().as_secs_f64();
        // Python's text mode: the decoded text with universal newlines.
        let stderr = self
            .runner
            .secrets()
            .scrub_with_patterns(&universal_newlines(&completed.stderr_text()), &patterns);
        Ok(PackagerResult {
            argv_redacted,
            // On Unix a process ends with a code or a signal, both of which the runner maps.
            returncode: completed.returncode.unwrap_or(-1),
            duration_s,
            stderr_tail: tail_chars(&stderr, STDERR_TAIL_CHARS),
        })
    }

    // --------------------------------------------------------------------------------------
    // decrypt (CENC) / encrypt (CBCS)
    // --------------------------------------------------------------------------------------

    /// Decrypt a raw-key CENC fMP4 to clear (`--enable_raw_key_decryption`):
    /// `<bin> input=<in>,stream=0,output=<out> --enable_raw_key_decryption --keys
    /// label=:key_id=<kid>:key=<key>`.
    ///
    /// Also decrypts the CBCS output for the 6-4 round trip: the "cenc" in the name is a
    /// The name does not restrict the encryption scheme.
    pub fn decrypt_cenc(
        &self,
        input_mp4: &Path,
        output_mp4: &Path,
        key: &KeyMaterial,
    ) -> Result<PackagerResult, Error> {
        let input_mp4 = utf8_path(input_mp4)?;
        let output_mp4 = utf8_path(output_mp4)?;
        #[cfg(unix)]
        make_dirs(&output_mp4.parent().to_path_buf())?;
        #[cfg(windows)]
        drop(crate::media::create_output_file(&output_mp4.to_path_buf())?);
        #[cfg(windows)]
        let _output_guard = crate::native::pin_media_directory(&output_mp4.parent().to_path_buf())?;
        let head = [
            self.binary.clone(),
            format!("input={input_mp4},stream=0,output={output_mp4}"),
            "--enable_raw_key_decryption".to_string(),
            "--keys".to_string(),
        ];
        // The real argv is built in place, so no unwiped copy of the key outlives the call.
        let mut argv_real: Zeroizing<Vec<String>> = Zeroizing::new(head.to_vec());
        argv_real.push(keys_arg(key, false));
        let argv_redacted = [&head[..], &[keys_arg(key, true)]].concat();
        self.run_packager(&argv_real, argv_redacted, &[key.key_hex(), key.iv_hex()])
    }

    /// Re-encrypt clear fMP4 to raw-key CBCS: an init segment plus a `$Number$` segment
    /// series — `<bin> input=<in>,stream=0,init_segment=<init>,segment_template=<template>
    /// --enable_raw_key_encryption --protection_scheme cbcs --iv <iv> --segment_duration <n>
    /// --clear_lead 0 [--pssh <concatenated hex>] --keys label=:key_id=<kid>:key=<key>`.
    ///
    /// `segment_template` is Shaka's STAGING template (1-origin `$Number$`, as written — not
    /// normalized); the caller renames with [`renumber_to_source_origin`]. `pssh_hex` boxes are
    /// concatenated verbatim into one `--pssh` value; when empty no `--pssh` is emitted (real
    /// Shaka then still writes a v1 common PSSH box into the init segment — expected).
    ///
    /// `segment_duration_seconds` has no default: leaving it out does not
    /// compile, so a hardcoded duration cannot slip in.
    ///
    /// ```no_run
    /// # use drmr_core::{config::KeyMaterial, events::NoSink, packager::Packager, toolrun::{Secrets, ToolRunner}};
    /// # use std::{path::Path, sync::Arc};
    /// # let packager = Packager::new(Arc::new(ToolRunner::new(Arc::new(Secrets::new()), Arc::new(NoSink))));
    /// # let key = KeyMaterial::new("00".repeat(16), "00".repeat(16), "00".repeat(16)).unwrap();
    /// packager.encrypt_cbcs(Path::new("clear.mp4"), Path::new("cbcs/init.mp4"), "cbcs/seg_$Number$.m4s", &key, 6.0, &[]);
    /// ```
    ///
    /// ```compile_fail
    /// # use drmr_core::{config::KeyMaterial, events::NoSink, packager::Packager, toolrun::{Secrets, ToolRunner}};
    /// # use std::{path::Path, sync::Arc};
    /// # let packager = Packager::new(Arc::new(ToolRunner::new(Arc::new(Secrets::new()), Arc::new(NoSink))));
    /// # let key = KeyMaterial::new("00".repeat(16), "00".repeat(16), "00".repeat(16)).unwrap();
    /// packager.encrypt_cbcs(Path::new("clear.mp4"), Path::new("cbcs/init.mp4"), "cbcs/seg_$Number$.m4s", &key, &[]);
    /// ```
    pub fn encrypt_cbcs(
        &self,
        input_mp4: &Path,
        init_output: &Path,
        segment_template: &str,
        key: &KeyMaterial,
        segment_duration_seconds: f64,
        pssh_hex: &[&str],
    ) -> Result<PackagerResult, Error> {
        let input_mp4 = utf8_path(input_mp4)?;
        let init_output = utf8_path(init_output)?;
        make_dirs(&init_output.parent().to_path_buf())?;
        make_dirs(
            &PurePosixPath::from_path(Path::new(segment_template))
                .parent()
                .to_path_buf(),
        )?;
        #[cfg(windows)]
        let _init_guard = crate::native::pin_media_directory(&init_output.parent().to_path_buf())?;
        #[cfg(windows)]
        let _segment_guard = crate::native::pin_media_directory(
            &PurePosixPath::from_path(Path::new(segment_template))
                .parent()
                .to_path_buf(),
        )?;
        // The real and the redacted argv share every token but the --iv value and the key.
        let prefix = [
            self.binary.clone(),
            format!(
                "input={input_mp4},stream=0,init_segment={init_output},\
                 segment_template={segment_template}"
            ),
            "--enable_raw_key_encryption".to_string(),
            "--protection_scheme".to_string(),
            "cbcs".to_string(),
            "--iv".to_string(),
        ];
        // HARD INVARIANT (segment duration derived, not hardcoded): the caller's
        // The duration comes from source metadata rather than a fixed constant.
        // HARD INVARIANT (no clear content): Shaka's --clear_lead defaults to 5 s, shorter than
        // the 6 s segment, which would leave the ENTIRE first segment of every rendition in the
        // clear — 0 encrypts from t=0. No secret: in both argvs.
        let middle = [
            "--segment_duration".to_string(),
            format_duration(segment_duration_seconds)?,
            "--clear_lead".to_string(),
            "0".to_string(),
        ];
        // HARD INVARIANT (PSSH via --pssh): the caller's boxes verbatim, concatenated;
        // --protection_systems is never emitted.
        let pssh: Vec<String> = if pssh_hex.is_empty() {
            Vec::new()
        } else {
            vec!["--pssh".to_string(), pssh_hex.concat()]
        };
        // HARD INVARIANT (explicit --iv): the configured 16-byte IV, so the output is
        // deterministic and the CBCS constant IV equals the FairPlay EXT-X-KEY IV=. The real
        // argv is built in place, so no unwiped copy of the key or the IV outlives the call.
        let mut argv_real: Zeroizing<Vec<String>> = Zeroizing::new(prefix.to_vec());
        argv_real.push(key.iv_hex().to_string());
        argv_real.extend(middle.iter().cloned());
        argv_real.extend(pssh.iter().cloned());
        argv_real.push("--keys".to_string());
        argv_real.push(keys_arg(key, false));
        let argv_redacted = [
            &prefix[..],
            &[REDACTED.to_string()],
            &middle,
            &pssh,
            &["--keys".to_string(), keys_arg(key, true)],
        ]
        .concat();
        let result =
            self.run_packager(&argv_real, argv_redacted, &[key.key_hex(), key.iv_hex()])?;
        #[cfg(windows)]
        {
            crate::native::seal_media_tree(&init_output.parent().to_path_buf())?;
            let segment_parent = PurePosixPath::from_path(Path::new(segment_template))
                .parent()
                .to_path_buf();
            if segment_parent != init_output.parent().to_path_buf() {
                crate::native::seal_media_tree(&segment_parent)?;
            }
        }
        Ok(result)
    }

    // --------------------------------------------------------------------------------------
    // boundary-preserving CBCS transcryption, per source segment
    // --------------------------------------------------------------------------------------

    /// Boundary-preserving CENC → CBCS transcryption, one SOURCE segment at a time: for each
    /// source segment `i`, merge `init || segment[i]`, decrypt it, re-encrypt it CBCS in
    /// isolation under [`ISOLATING_SEGMENT_DURATION_S`] (so Shaka emits exactly one output
    /// segment whose boundary is the source segment's), and place it as `seg_{i+1}` of the
    /// caller's 1-origin staging series ([`renumber_to_source_origin`] reconciles it). The CBCS
    /// init is written once, from segment 0. Absolute decode times are preserved end to end, so
    /// each output `tfdt` equals the source's and the 6-4 round trip stays bit-exact.
    ///
    /// Returns `returncode == 0` on success (the last encrypt's redacted argv, the summed run
    /// time, no stderr); on the first failed run, that run's scrubbed result; on an isolation
    /// breach, a result carrying [`ISOLATION_VIOLATION_RC`]. A spawn failure or a timeout is
    /// the delegated [`PackagerError`]. Every child goes through the delegated functions, which
    /// redact; this function never builds an argv from the key itself.
    ///
    /// HARD INVARIANT (inputs read-only): reads `init_path` and `segment_paths`; writes only
    /// under `work_dir` (default `<init_output's dir>/_persegment_work`), the template's
    /// directory and `init_output`.
    #[allow(clippy::too_many_arguments)] // reason: Python's signature, argument for argument
    pub fn transcrypt_cbcs_per_segment(
        &self,
        init_path: &Path,
        segment_paths: &[PathBuf],
        init_output: &Path,
        segment_template: &str,
        key: &KeyMaterial,
        pssh_hex: &[&str],
        work_dir: Option<&Path>,
    ) -> Result<PackagerResult, Error> {
        // Paths joined as `pathlib` joins them (a `.` part dropped: `Path(".") / "x"` is `x`), so
        // the per-segment template on the argv is spelled as Python spells it.
        let init_output = utf8_path(init_output)?;
        make_dirs(&init_output.parent().to_path_buf())?;
        make_dirs(
            &PurePosixPath::from_path(Path::new(segment_template))
                .parent()
                .to_path_buf(),
        )?;
        let work = match work_dir {
            Some(work_dir) => utf8_path(work_dir)?,
            None => init_output.parent().join("_persegment_work"),
        };
        make_dirs(&work.to_path_buf())?;
        #[cfg(windows)]
        let _init_guard = crate::native::pin_media_directory(&init_output.parent().to_path_buf())?;
        #[cfg(windows)]
        let _segment_guard = crate::native::pin_media_directory(
            &PurePosixPath::from_path(Path::new(segment_template))
                .parent()
                .to_path_buf(),
        )?;
        #[cfg(windows)]
        let _work_guard = crate::native::pin_media_directory(&work.to_path_buf())?;
        let mut total_duration = 0.0;
        let mut last_redacted = Vec::new();
        for (index, source_segment) in segment_paths.iter().enumerate() {
            let segment_work = work.join(&format!("seg_{index}"));
            let segment_dir = segment_work.to_path_buf();
            if segment_dir.exists() {
                std::fs::remove_dir_all(&segment_dir)?;
            }
            make_dirs(&segment_dir)?;
            let merged = merge_segments(
                init_path,
                std::slice::from_ref(source_segment),
                &segment_work.join("source.mp4").to_path_buf(),
            )?;
            let clear = segment_work.join("clear.mp4").to_path_buf();
            let decrypted = self.decrypt_cenc(&merged, &clear, key)?;
            total_duration += decrypted.duration_s;
            if decrypted.returncode != 0 {
                return Ok(decrypted); // already scrubbed
            }
            let segment_init = segment_work.join("init.mp4").to_path_buf();
            let encrypted = self.encrypt_cbcs(
                &clear,
                &segment_init,
                &segment_work.join("out_$Number$.m4s").to_string(),
                key,
                ISOLATING_SEGMENT_DURATION_S,
                pssh_hex,
            )?;
            total_duration += encrypted.duration_s;
            last_redacted.clone_from(&encrypted.argv_redacted);
            if encrypted.returncode != 0 {
                return Ok(encrypted); // already scrubbed
            }
            let mut produced = Vec::new();
            for path in glob(&segment_dir, "out_*.m4s")? {
                produced.push((numeric_segment_key(&path)?, path));
            }
            produced.sort_by_key(|(key, _)| *key);
            if produced.len() != 1 {
                // The isolating duration MUST yield exactly one segment; more means the
                // boundary was re-decided (the drift again). Refuse — no secret in the tail.
                return Ok(PackagerResult {
                    argv_redacted: encrypted.argv_redacted,
                    returncode: ISOLATION_VIOLATION_RC,
                    duration_s: total_duration,
                    stderr_tail: format!(
                        "per-segment isolation produced {} segments for source segment index \
                         {index} (expected exactly 1)",
                        produced.len()
                    ),
                });
            }
            // Into the caller's 1-origin staging series (Shaka's; renumbered to the source's).
            let staging_number = index + 1;
            let final_segment =
                PathBuf::from(segment_template.replace("$Number$", &staging_number.to_string()));
            make_dirs(&parent_of(&final_segment))?;
            remove_file_if_present(&final_segment)?;
            move_file(&produced[0].1, &final_segment)?;
            if index == 0 {
                copy_file(&segment_init, &init_output.to_path_buf())?;
            }
            // Bound the scratch disk across ~100 segments per rendition (200k assets).
            let _ = std::fs::remove_dir_all(&segment_dir);
        }
        Ok(PackagerResult {
            argv_redacted: last_redacted,
            returncode: 0,
            duration_s: total_duration,
            stderr_tail: String::new(),
        })
    }
}

/// A path as `str(Path(path))` text: the argv carries text, so a path that is not UTF-8 is an
/// error here (Python would pass its surrogate-escaped bytes through; documented limit).
fn utf8_path(path: &Path) -> Result<PurePosixPath, Error> {
    match path.to_str() {
        Some(_) => Ok(PurePosixPath::from_path(path)),
        None => Err(Error::Value(format!(
            "path is not valid UTF-8: {}",
            path.display()
        ))),
    }
}

/// `path.unlink(missing_ok=True)`.
fn remove_file_if_present(path: &Path) -> Result<(), Error> {
    match std::fs::remove_file(path) {
        Err(error) if error.kind() != ErrorKind::NotFound => Err(error.into()),
        _ => Ok(()),
    }
}

/// `shutil.move(source, destination)` onto a destination that does not exist: a rename, or a
/// copy and an unlink across file systems.
fn move_file(source: &Path, destination: &Path) -> Result<(), Error> {
    if std::fs::rename(source, destination).is_err() {
        copy_file(source, destination)?;
        std::fs::remove_file(source)?;
    }
    Ok(())
}

/// `shutil.copyfile(source, destination)`: the content only (the destination created or
/// truncated with the default mode, as Python opens it).
fn copy_file(source: &Path, destination: &Path) -> Result<(), Error> {
    let mut input = File::open(source)?;
    let mut output = crate::media::create_output_file(destination)?;
    std::io::copy(&mut input, &mut output)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_timeout_message_prints_the_configured_seconds_as_python_does() {
        // Exercise fractional timeout formatting without waiting for the timeout.
        // configured float's repr.
        for (seconds, text) in [(7.5, "7.5"), (0.5, "0.5"), (2.0, "2.0"), (30.0, "30.0")] {
            assert_eq!(
                format!(
                    "Shaka Packager timed out after {}s",
                    python_float_repr(seconds)
                ),
                format!("Shaka Packager timed out after {text}s")
            );
        }
    }

    #[test]
    fn the_tail_keeps_the_last_characters() {
        assert_eq!(tail_chars("abcdef", 3), "def");
        assert_eq!(tail_chars("ab", 3), "ab");
        assert_eq!(tail_chars("日本語テキスト", 2), "スト");
    }
}
